Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

/// <summary>
/// The app drives this project's export itself via the public `ExportToPackage`/
/// `GetExecutionSummaryStatus`/`GetExportedPackageUrl` OData actions, the same flow
/// `CountingJournalRepository.startExport`/`pollExport` already use - see
/// HSMobileOpsSkuService::exportSkuMaster's own doc comment.
/// </summary>
[DataMemberAttribute('ItemDefinitionGroupName')]
public str parmItemDefinitionGroupName(str _value = itemDefinitionGroupName)
{
    itemDefinitionGroupName = _value;
    return itemDefinitionGroupName;
}

[DataMemberAttribute('BarcodeDefinitionGroupName')]
public str parmBarcodeDefinitionGroupName(str _value = barcodeDefinitionGroupName)
{
    barcodeDefinitionGroupName = _value;
    return barcodeDefinitionGroupName;
}
